-- Task 20 (the portal's language): content/seed.json, academy.json, tools.json and news.json follow the style guide
-- and glossary («» quotes, official register, grammar). A database seeded before (0461's e-service catalogue, a prod
-- catalogue, a demo database) still holds the old texts, which are no longer translation keys; an applied migration is
-- never edited, so this one rewrites them. Generated from the content diff: in a JSON column each changed string is
-- replaced as a whole JSON string; a text column is set only while it still holds the seeded text; the demo's news rows
-- are matched by their seeded text, so a prod database has none. tests/integration/test_service_honesty.py compares a
-- migrated database's e-services with content/seed.json.
UPDATE academy_modules SET quiz = replace(quiz, '"Generativ AI modelinin “halüsinasiya”sı nədir?"', '"Generativ AI modelinin «halüsinasiya»sı nədir?"') WHERE track_key = 'ai' AND seq = 1;
UPDATE academy_modules SET paragraphs = replace(replace(paragraphs, '"AI tutorun keyfiyyəti yüklənən materialların keyfiyyətindən asılıdır. Materialları başlıqlarla strukturlaşdırın, əsas anlayışları “Termin — tərif” formatında yazın, düsturları ayrıca sətirdə verin."', '"AI tutorun keyfiyyəti yüklənən materialların keyfiyyətindən asılıdır. Materialları başlıqlarla strukturlaşdırın, əsas anlayışları «Termin — tərif» formatında yazın, düsturları ayrıca sətirdə verin."'), '"Tutor qaydaları bölməsində fənnə xas tələbləri yazın, məsələn: “Vahidləri həmişə SI sistemində göstər”."', '"Tutor qaydaları bölməsində fənnə xas tələbləri yazın, məsələn: «Vahidləri həmişə SI sistemində göstər»."') WHERE track_key = 'ai' AND seq = 2;
UPDATE academy_modules SET key_points = replace(key_points, '"Strukturlu material — keyfiyyətli tutor"', '"Strukturlaşdırılmış material — keyfiyyətli tutor"') WHERE track_key = 'ai' AND seq = 2;
UPDATE academy_modules SET quiz = replace(quiz, '"“Termin — tərif” formatında"', '"«Termin — tərif» formatında"') WHERE track_key = 'ai' AND seq = 2;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"Nəticələrin analizi zamanı sualın çətinlik indeksinə baxın: tələbələrin 90%-dən çoxu düzgün cavab veribsə, sual çox asan, 30%-dən azı düzgün cavab veribsə, sual ya çətin, ya da qeyri-dəqiq ola bilər."', '"Nəticələri təhlil edərkən sualın çətinlik indeksinə baxın: tələbələrin 90%-dən çoxu düzgün cavab veribsə, sual çox asandır; 30%-dən azı düzgün cavab veribsə, sual ya çətin, ya da qeyri-dəqiq ola bilər."') WHERE track_key = 'ai' AND seq = 3;
UPDATE academy_modules SET key_points = replace(key_points, '"AI sualları təsdiqsiz tələbəyə getmir"', '"AI-ın yaratdığı suallar təsdiqlənmədən tələbəyə göndərilmir"') WHERE track_key = 'ai' AND seq = 3;
UPDATE academy_modules SET quiz = replace(quiz, '"Tələbələrin 95%-i düzgün cavab verən sual haqqında nə demək olar?"', '"Tələbələrin 95%-inin düzgün cavab verdiyi sual haqqında nə demək olar?"') WHERE track_key = 'ai' AND seq = 3;
UPDATE academy_modules SET paragraphs = replace(replace(replace(paragraphs, '"AI aşkarlayıcı alətlər etibarlı deyil: araşdırmalar göstərir ki, ana dili ingilis dili olmayan tələbələrin mətnləri tez-tez səhvən “AI tərəfindən yazılmış” kimi qiymətləndirilir. Ona görə aşkarlayıcının nəticəsi heç vaxt yeganə sübut olmamalıdır."', '"AI aşkarlama alətləri etibarlı deyil: araşdırmalar göstərir ki, ana dili ingilis dili olmayan tələbələrin mətnləri tez-tez səhvən «AI tərəfindən yazılmış» kimi qiymətləndirilir. Buna görə də aşkarlayıcının nəticəsi heç vaxt yeganə sübut olmamalıdır."'), '"Dürüstlüyü təmin etməyin daha effektiv yolu tapşırıqların dizaynıdır: prosesə əsaslanan qiymətləndirmə, şifahi müdafiə, fərdi məlumatlarla tapşırıqlar və AI-dan istifadənin açıq qaydaları."', '"Dürüstlüyü təmin etməyin daha effektiv yolu tapşırıqların dizaynıdır: prosesə əsaslanan qiymətləndirmə, şifahi müdafiə, fərdi variantlı tapşırıqlar və AI-dan istifadənin aydın qaydaları."'), '"Tələbələrə AI-dan necə düzgün istifadə etməyi öyrədin: ideya axtarışı və izah üçün bəli, hazır işi öz adına təqdim etmək üçün xeyr."', '"Tələbələrə AI-dan düzgün istifadə etməyi öyrədin: ideya axtarışı və izah üçün bəli, hazır işi öz adına təqdim etmək üçün xeyr."') WHERE track_key = 'ai' AND seq = 4;
UPDATE academy_modules SET task = 'Tapşırıqlarınızdan birini AI ilə asanlıqla yerinə yetirilə bilməyəcək şəkildə yenidən qurun (məsələn, şifahi müdafiə mərhələsi əlavə edin).' WHERE track_key = 'ai' AND seq = 4 AND task = 'Bir tapşırığınızı AI-a davamlı olacaq şəkildə yenidən qurun (məsələn, şifahi müdafiə mərhələsi əlavə edin).';
UPDATE academy_modules SET quiz = replace(quiz, '"AI aşkarlayıcının nəticəsi necə istifadə olunmalıdır?"', '"AI aşkarlayıcısının nəticəsindən necə istifadə edilməlidir?"') WHERE track_key = 'ai' AND seq = 4;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"AI-a tələbənin adı, FİN kodu, telefon nömrəsi və digər şəxsi məlumatlarını yazmayın. Qiymət, qəbul və intizam qərarları kimi mühüm qərarlarda son söz həmişə insanda qalmalıdır."', '"AI-a tələbənin adını, FİN kodunu, telefon nömrəsini və digər şəxsi məlumatlarını yazmayın. Qiymət, qəbul və intizam qərarları kimi mühüm qərarlarda son söz həmişə insanda qalmalıdır."') WHERE track_key = 'ai' AND seq = 5;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"Parametrik suallar hər tələbəyə fərqli rəqəmlərlə məsələ verməyə imkan yaradır. Bu həm köçürmənin qarşısını alır, həm də tələbəyə qeyri-məhdud məşq imkanı verir."', '"Parametrik suallar hər tələbəyə fərqli ədədlərlə məsələ verməyə imkan yaradır. Bu həm köçürmənin qarşısını alır, həm də tələbəyə qeyri-məhdud məşq imkanı verir."') WHERE track_key = 'ai' AND seq = 6;
UPDATE academy_modules SET quiz = replace(quiz, '"Hər tələbəyə fərqli rəqəmlərlə məsələ verilməsi"', '"Hər tələbəyə fərqli ədədlərlə məsələ verilməsi"') WHERE track_key = 'ai' AND seq = 6;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"Effektiv rəy konkret, vaxtında və tətbiq oluna bilən olmalıdır. “Yaxşıdır” və ya “zəifdir” əvəzinə nəyin yaxşı alındığını və nəyi necə yaxşılaşdırmaq lazım olduğunu göstərin."', '"Effektiv rəy konkret, vaxtında və tətbiq oluna bilən olmalıdır. «Yaxşıdır» və ya «zəifdir» əvəzinə nəyin yaxşı alındığını və nəyi necə yaxşılaşdırmaq lazım olduğunu göstərin."') WHERE track_key = 'communication' AND seq = 1;
UPDATE academy_modules SET key_points = replace(key_points, '"İşi qiymətləndirin, şəxsi yox"', '"Şəxsiyyəti deyil, işi qiymətləndirin"') WHERE track_key = 'communication' AND seq = 1;
UPDATE academy_modules SET quiz = replace(replace(replace(replace(quiz, '"“Zəifdir, yenidən et.”"', '"«Zəifdir, yenidən et»."'), '"“Hesablamalar düzgündür; vahidləri hər addımda yazsan, səhvləri tez tapacaqsan.”"', '"«Hesablamalar düzgündür; vahidləri hər addımda yazsan, səhvləri tez tapacaqsan»."'), '"“Pis deyil.”"', '"«Pis deyil»."'), '"“Bunu niyə belə etmisən?”"', '"«Bunu niyə belə etmisən?»"') WHERE track_key = 'communication' AND seq = 1;
UPDATE academy_modules SET quiz = replace(quiz, '"IMRaD strukturunda “R” nəyi bildirir?"', '"IMRaD strukturunda «R» nəyi bildirir?"') WHERE track_key = 'communication' AND seq = 2;
UPDATE academy_modules SET paragraphs = replace(replace(paragraphs, '"10–15 dəqiqəlik çıxışda bir əsas mesaj seçin və bütün slaydları ona xidmət etdirin. Hər slaydda bir fikir və minimum mətn olsun."', '"10–15 dəqiqəlik çıxış üçün bir əsas mesaj seçin: bütün slaydlar ona xidmət etməlidir. Hər slaydda bir fikir və minimum mətn olsun."'), '"Çıxışı vaxtla ən azı iki dəfə məşq edin; vaxt limitini aşmaq auditoriyaya hörmətsizlik kimi qəbul olunur."', '"Çıxışı vaxtı ölçərək ən azı iki dəfə məşq edin; vaxt limitini aşmaq auditoriyaya hörmətsizlik kimi qəbul olunur."') WHERE track_key = 'communication' AND seq = 3;
UPDATE academy_modules SET quiz = replace(replace(quiz, '"Çıxışı vaxtla məşq edib limitə riayət etmək"', '"Çıxışı vaxtı ölçərək məşq edib limitə riayət etmək"'), '"Yarısında dayanmaq"', '"Yarıda dayanmaq"') WHERE track_key = 'communication' AND seq = 3;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"Tələbələrlə yazışmada rəsmi kanallardan istifadə edin və cavab müddəti barədə gözləntiləri əvvəlcədən bildirin, məsələn, iki iş günü ərzində."', '"Tələbələrlə yazışmada rəsmi kanallardan istifadə edin və cavab müddətini əvvəlcədən bildirin, məsələn, iki iş günü ərzində."') WHERE track_key = 'communication' AND seq = 4;
UPDATE academy_modules SET task = 'Tələbələr üçün «mənimlə necə əlaqə saxlamalı» qaydasını 3 cümlə ilə yazın.' WHERE track_key = 'communication' AND seq = 4 AND task = 'Tələbələr üçün “mənimlə necə əlaqə saxlamalı” qaydasını 3 cümlə ilə yazın.';
UPDATE academy_modules SET quiz = replace(quiz, '"Gözləntini əvvəlcədən bildirmək"', '"Cavab müddətini əvvəlcədən bildirmək"') WHERE track_key = 'communication' AND seq = 4;
UPDATE academy_modules SET paragraphs = replace(replace(paragraphs, '"Simulyasiyalar bahalı, təhlükəli və ya mürəkkəb təcrübələri vizual və təkrarlanan edir. Onlar real laboratoriyanı əvəz etmir, lakin laboratoriyaya hazırlıq və nəzəriyyəni anlamaq üçün çox effektivdir."', '"Simulyasiyalar bahalı, təhlükəli və ya mürəkkəb təcrübələri vizual və təkrarlana bilən edir. Onlar real laboratoriyanı əvəz etmir, lakin laboratoriyaya hazırlıq və nəzəriyyəni anlamaq üçün çox effektivdir."'), '"Ən yaxşı nəticə “proqnoz ver — yoxla — izah et” ssenarisi ilə alınır: tələbə əvvəlcə nəticəni proqnozlaşdırır, sonra simulyasiyada yoxlayır."', '"Ən yaxşı nəticə «proqnoz ver — yoxla — izah et» ssenarisi ilə alınır: tələbə əvvəlcə nəticəni proqnozlaşdırır, sonra simulyasiyada yoxlayır."') WHERE track_key = 'edtech' AND seq = 1;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"Yalnız “keçdi/keçmədi” rəyi kifayət deyil: tələbədən öz test nümunələrini yazmağı da tələb edin ki, avtomatik yoxlamaya həddən artıq asılılıq yaranmasın."', '"Yalnız «keçdi/keçmədi» rəyi kifayət deyil: tələbədən öz test nümunələrini yazmağı da tələb edin ki, avtomatik yoxlamaya həddən artıq asılılıq yaranmasın."') WHERE track_key = 'edtech' AND seq = 2;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"Müasir mühəndis qrafikası tədrisi CAD sistemləri olmadan mümkün deyil. AutoCAD, FreeCAD və Onshape kimi alətlər iki ölçülü çertyojdan üç ölçülü parametrik modelə qədər bütün mərhələləri əhatə edir."', '"Müasir mühəndis qrafikası tədrisi CAD sistemləri olmadan mümkün deyil. AutoCAD, FreeCAD və Onshape kimi alətlər ikiölçülü çertyojdan üçölçülü parametrik modelə qədər bütün mərhələləri əhatə edir."') WHERE track_key = 'edtech' AND seq = 4;
UPDATE academy_modules SET quiz = replace(quiz, '"Pulun olmaması"', '"Pulsuz olması"') WHERE track_key = 'edtech' AND seq = 4;
UPDATE academy_modules SET paragraphs = replace(replace(replace(paragraphs, '"İkinci dildə dinləyən tələbə üçün mühazirənin strukturu məzmun qədər vacibdir. İlk dəqiqələrdə mövzunu, planı və dərsin sonunda nəyi bacaracaqlarını açıq deyin."', '"Mühazirəni ikinci dildə dinləyən tələbələr üçün onun strukturu məzmun qədər vacibdir. İlk dəqiqələrdə mövzunu, planı və dərsin sonunda nəyi bacaracaqlarını aydın bildirin."'), '"Keçid ifadələri (signposting) dinləyiciyə harada olduğunu göstərir: hər yeni hissəyə keçəndə bunu səslə bildirin və əvvəlki hissəni bir cümlə ilə yekunlaşdırın."', '"Keçid ifadələri (signposting) dinləyiciyə harada olduğunu göstərir: hər yeni hissəyə keçərkən bunu səsləndirin və əvvəlki hissəni bir cümlə ilə yekunlaşdırın."'), '"Sürəti azaldın, açar terminləri lövhədə yazın və hər 10–15 dəqiqədən bir qısa xülasə edin."', '"Danışıq tempini azaldın, açar terminləri lövhəyə yazın və hər 10–15 dəqiqədən bir qısa xülasə verin."') WHERE track_key = 'emi' AND seq = 1;
UPDATE academy_modules SET key_points = replace(key_points, '"Hər keçidi səslə bildirin"', '"Hər keçidi səsləndirin"') WHERE track_key = 'emi' AND seq = 1;
UPDATE academy_modules SET phrases = replace(phrases, '"Yekunlaşdıraraq …"', '"Yekun olaraq, …"') WHERE track_key = 'emi' AND seq = 1;
UPDATE academy_modules SET quiz = replace(replace(replace(replace(replace(quiz, '"“Signposting” ifadələrinin əsas məqsədi nədir?"', '"«Signposting» ifadələrinin əsas məqsədi nədir?"'), '"“OK, let''s start, page 45.”"', '"«OK, let''s start, page 45.»"'), '"“Today we''re going to look at Kirchhoff''s laws. By the end, you will be able to analyse simple circuits.”"', '"«Today we''re going to look at Kirchhoff''s laws. By the end, you will be able to analyse simple circuits.»"'), '"“You know this topic already.”"', '"«You know this topic already.»"'), '"“No questions, please.”"', '"«No questions, please.»"') WHERE track_key = 'emi' AND seq = 1;
UPDATE academy_modules SET paragraphs = replace(replace(replace(paragraphs, '"Tərif verərkən “X is a device which/that …” və ya “X is used to …” quruluşlarından istifadə edin. Əvvəlcə sadə, sonra dəqiq tərif verin."', '"Tərif verərkən «X is a device which/that …» və ya «X is used to …» quruluşlarından istifadə edin. Əvvəlcə sadə, sonra dəqiq tərif verin."'), '"Anlayışı başqa sözlərlə təkrarlamaq (paraphrasing) və nümunə vermək anlaşılmanı kəskin artırır: “In other words …”, “For example …”."', '"Anlayışı başqa sözlərlə təkrarlamaq (paraphrasing) və nümunə vermək anlaşılmanı xeyli artırır: «In other words …», «For example …»."'), '"Başa düşülüb-düşülmədiyini “Do you understand?” sualı ilə yox, yoxlayıcı suallarla öyrənin: “What happens to the current if we double the resistance?”"', '"Başa düşülüb-düşülmədiyini «Do you understand?» sualı ilə yox, yoxlayıcı suallarla öyrənin: «What happens to the current if we double the resistance?»"') WHERE track_key = 'emi' AND seq = 2;
UPDATE academy_modules SET key_points = replace(key_points, '"“Do you understand?” əvəzinə yoxlayıcı sual verin"', '"«Do you understand?» əvəzinə yoxlayıcı sual verin"') WHERE track_key = 'emi' AND seq = 2;
UPDATE academy_modules SET quiz = replace(replace(replace(replace(replace(quiz, '"“Do you understand?” soruşmaq"', '"«Do you understand?» deyə soruşmaq"'), '"“X is a device which converts …”"', '"«X is a device which converts …»"'), '"“X very important”"', '"«X very important»"'), '"“X — that''s all”"', '"«X — that''s all»"'), '"“X is used for to convert …”"', '"«X is used for to convert …»"') WHERE track_key = 'emi' AND seq = 2;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"Sual verən tələbəni həvəsləndirin və sualı bütün auditoriya üçün təkrarlayın. Sual aydın deyilsə, nəzakətlə yenidən ifadə etməyi xahiş edin."', '"Sual verən tələbəni həvəsləndirin və sualı bütün auditoriya üçün təkrarlayın. Sual aydın deyilsə, nəzakətlə onu başqa sözlərlə ifadə etməsini xahiş edin."') WHERE track_key = 'emi' AND seq = 3;
UPDATE academy_modules SET phrases = replace(replace(phrases, '"Buna sonra qayıdım."', '"İcazə verin, bu suala sonra qayıdım."'), '"Cüt halında işləyin. Beş dəqiqə vaxtınız var."', '"Cütlərlə işləyin. Beş dəqiqə vaxtınız var."') WHERE track_key = 'emi' AND seq = 3;
UPDATE academy_modules SET quiz = replace(replace(quiz, '"“Let me get back to you on that.” deyib sonra cavab vermək"', '"«Let me get back to you on that.» deyib sonra cavab vermək"'), '"Heç bir vaxt limiti"', '"Heç bir vaxt limitinin olmaması"') WHERE track_key = 'emi' AND seq = 3;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"İlk yazışmada “Dear Professor Smith,” və ya “Dear Dr Smith,” müraciəti, sonda “Kind regards,” və ya “Best regards,” uyğundur."', '"İlk yazışmada «Dear Professor Smith,» və ya «Dear Dr Smith,» müraciəti, sonda «Kind regards,» və ya «Best regards,» uyğundur."') WHERE track_key = 'emi' AND seq = 4;
UPDATE academy_modules SET quiz = replace(replace(replace(replace(replace(replace(replace(replace(quiz, '"“Bye!”"', '"«Bye!»"'), '"“Kind regards,”"', '"«Kind regards,»"'), '"“See ya”"', '"«See ya»"'), '"“Thx”"', '"«Thx»"'), '"“Hello”"', '"«Hello»"'), '"“Joint seminar proposal: AI in Engineering Education, March 2027”"', '"«Joint seminar proposal: AI in Engineering Education, March 2027»"'), '"“Important!!!”"', '"«Important!!!»"'), '"Boş saxlamaq"', '"Boş buraxmaq"') WHERE track_key = 'emi' AND seq = 4;
UPDATE academy_modules SET paragraphs = replace(paragraphs, '"“Düşün–cütləş–paylaş” texnikasında tələbə əvvəl fərdi düşünür, sonra cütlə müzakirə edir və nəticəni auditoriya ilə bölüşür. “Bir dəqiqəlik yazı” dərsin sonunda ən aydın olmayan məqamı üzə çıxarır."', '"«Düşün–cütləş–paylaş» texnikasında tələbə əvvəl fərdi düşünür, sonra cütlükdə müzakirə edir və nəticəni auditoriya ilə bölüşür. «Bir dəqiqəlik yazı» dərsin sonunda ən çətin anlaşılan məqamı üzə çıxarır."') WHERE track_key = 'pedagogy' AND seq = 1;
UPDATE academy_modules SET task = 'Növbəti mühazirənizə bir «düşün–cütləş–paylaş» sualı əlavə edin.' WHERE track_key = 'pedagogy' AND seq = 1 AND task = 'Növbəti mühazirənizə bir “düşün–cütləş–paylaş” sualı əlavə edin.';
UPDATE academy_modules SET quiz = replace(replace(quiz, '"“Düşün–cütləş–paylaş” texnikasının ilk addımı hansıdır?"', '"«Düşün–cütləş–paylaş» texnikasının ilk addımı hansıdır?"'), '"“Bir dəqiqəlik yazı” nə üçün istifadə olunur?"', '"«Bir dəqiqəlik yazı» nə üçün istifadə olunur?"') WHERE track_key = 'pedagogy' AND seq = 1;
UPDATE academy_modules SET paragraphs = replace(replace(paragraphs, '"Yırtıcı jurnalların əlamətləri: kütləvi dəvət məktubları, bir neçə günlük “rəy”, qeyri-şəffaf ödənişlər və redaksiya heyəti haqqında yoxlanıla bilməyən məlumat."', '"Yırtıcı jurnalların əlamətləri: kütləvi dəvət məktubları, bir neçə günlük «rəy», qeyri-şəffaf ödənişlər və redaksiya heyəti haqqında yoxlanıla bilməyən məlumat."'), '"“Think. Check. Submit.” yoxlama siyahısı jurnal seçərkən sadə və faydalı vasitədir."', '"«Think. Check. Submit.» yoxlama siyahısı jurnal seçərkən sadə və faydalı vasitədir."') WHERE track_key = 'research' AND seq = 1;
